export function sleepPhaseMemoryReplay(memoryData) {
  const replayedMemories = memoryData.filter(memory => memory.priority > 0.8);
  replayedMemories.forEach(memory => {
    memory.semanticLinks.forEach(link => {
      link.strength += 0.1 * memory.importance;
    });
    memory.proceduralSteps.forEach(step => {
      step.reinforce();
    });
  });
  return replayedMemories;
}